data class Team(val name: String, val score: Int)

fun sortByScore(teams: List<Team>): List<Team> {
    return teams.sortedByDescending { it.score }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testSortByScore() {
        val teams = listOf(
            Team("Tribots", 85),
            Team("Gearheads", 72),
            Team("RoboWolves", 91)
        )
        val sorted = sortByScore(teams)
        Assert.assertEquals("RoboWolves", sorted[0].name)
        Assert.assertEquals("Tribots", sorted[1].name)
        Assert.assertEquals("Gearheads", sorted[2].name)
    }

    @Test
    fun testSingleTeam() {
        val teams = listOf(Team("Tribots", 85))
        Assert.assertEquals(1, sortByScore(teams).size)
    }
}
